	protected static CloseableIteration<BindingSet> evaluate(TupleFunction func,
			final List<Var> resultVars, final BindingSet bindings, ValueFactory valueFactory, Value... argValues)
			throws QueryEvaluationException {
		CloseableIteration<? extends List<? extends Value>> iter;
		QueryExecutionContext.initializeExternalValues(argValues);
		try (QueryExecutionContext.Activation ignored = QueryExecutionContext.deferReplaySafepoints()) {
			iter = func.evaluate(valueFactory, argValues);
		}
		try {
			QueryExecutionContext.checkpointReplaySafepoint();
			final CloseableIteration<? extends List<? extends Value>> resultIteration = iter;
			return new LookAheadIteration<>() {

				@Override
				public BindingSet getNextElement() throws QueryEvaluationException {
					try {
						QueryBindingSet resultBindings = null;
						while (resultBindings == null) {
							boolean hasNext;
							try (QueryExecutionContext.Activation ignored = QueryExecutionContext
									.deferReplaySafepoints()) {
								hasNext = iter.hasNext();
							}
							QueryExecutionContext.checkpointReplaySafepoint();
							if (!hasNext) {
								break;
							}
							resultBindings = new QueryBindingSet(bindings);
							List<? extends Value> values;
							try (QueryExecutionContext.Activation ignored = QueryExecutionContext
									.deferReplaySafepoints()) {
								values = iter.next();
							}
							QueryExecutionContext.checkpointReplaySafepoint();
							if (resultVars.size() != values.size()) {
								throw new QueryEvaluationException(
										"Incorrect number of result vars: require " + values.size());
							}
							for (int i = 0; i < values.size(); i++) {
								Value result = values.get(i);
								Var resultVar = resultVars.get(i);
								Value varValue = resultVar.getValue();
								String varName = resultVar.getName();
								Value boundValue = bindings.getValue(varName);
								if ((varValue == null || result.equals(varValue))
										&& (boundValue == null || result.equals(boundValue))) {
									if (boundValue == null) { // if not already present
										resultBindings.addBinding(varName, result);
									}
								} else {
									resultBindings = null;
									break;
								}
							}
						}
						return resultBindings;
					} catch (RuntimeException | Error failure) {
						ExternalValuePreparation.closeWithSuppressed(this, failure);
						throw failure;
					}
				}

				@Override
				protected void handleClose() throws QueryEvaluationException {
					resultIteration.close();
				}
			};
		} catch (RuntimeException | Error failure) {
			ExternalValuePreparation.closeWithSuppressed(iter, failure);
			throw failure;
		}
	}

	private QueryExecutionPolicy queryExecutionPolicy = QueryExecutionPolicy.DEFAULT;
	private boolean queryExecutionPolicyBound;
	private boolean queryPreparationStarted;

	@Override
	public QueryExecutionPolicy getQueryExecutionPolicy() {
		return queryExecutionPolicy;
	}

	@Override
	public synchronized void setQueryExecutionPolicy(QueryExecutionPolicy policy) {
		Objects.requireNonNull(policy);
		if ((queryExecutionPolicyBound || queryPreparationStarted) && queryExecutionPolicy != policy) {
			throw new IllegalStateException("Query execution policy is already bound to this strategy");
		}
		queryExecutionPolicy = policy;
		queryExecutionPolicyBound = true;
	}

	/** Shared preparation boundary for this strategy and backend subclasses. */
	protected final TupleExpr prepareTupleExpr(TupleExpr expression) {
		if (expression == null) {
			throw new IllegalArgumentException("expr must not be null");
		}
		synchronized (this) {
			queryPreparationStarted = true;
		}
		return PreparedValuesSnapshot.prepare(expression);
	}

	/** A preparation phase owns snapshots; a safety-only caller scope does not imply row capture. */
	protected final <T> T withPreparedTupleExpr(TupleExpr expression,
			java.util.function.Function<TupleExpr, T> action) {
		if (expression == null) {
			throw new IllegalArgumentException("expr must not be null");
		}
		synchronized (this) {
			queryPreparationStarted = true;
		}
		return QueryEvaluationUtility.withPreparedQuerySafetySnapshot(expression, getQueryExecutionPolicy(),
				PreparedValuesSnapshot::newPreparation,
				action);
	}

	public DefaultEvaluationStrategy(TripleSource tripleSource, FederatedServiceResolver serviceResolver) {
		this(tripleSource, null, serviceResolver);
	}

	public DefaultEvaluationStrategy(TripleSource tripleSource, Dataset dataset,
			FederatedServiceResolver serviceResolver) {
		this(tripleSource, dataset, serviceResolver, 0, new EvaluationStatistics());
	}

	public DefaultEvaluationStrategy(TripleSource tripleSource, Dataset dataset,
			FederatedServiceResolver serviceResolver, long iterationCacheSyncTreshold,
			EvaluationStatistics evaluationStatistics) {
		this(tripleSource, dataset, serviceResolver, iterationCacheSyncTreshold, evaluationStatistics, false);
	}

	public DefaultEvaluationStrategy(TripleSource tripleSource, Dataset dataset,
			FederatedServiceResolver serviceResolver, long iterationCacheSyncTreshold,
			EvaluationStatistics evaluationStatistics, boolean trackResultSize) {
		this(tripleSource, dataset, serviceResolver, iterationCacheSyncTreshold, evaluationStatistics, trackResultSize,
				TupleFunctionRegistry.getInstance());
	}

	public DefaultEvaluationStrategy(TripleSource tripleSource, Dataset dataset,
			FederatedServiceResolver serviceResolver, long iterationCacheSyncTreshold,
			EvaluationStatistics evaluationStatistics, boolean trackResultSize,
			TupleFunctionRegistry tupleFunctionRegistry) {
		this.tripleSource = tripleSource;
		this.dataset = dataset;
		this.blankNodes = BlankNodeAllocationScope.currentOrNew();
		if (tripleSource != null) {
			this.blankNodes.bindLocalValueFactory(tripleSource.getValueFactory());
		}
		this.serviceResolver = serviceResolver;
		this.iterationCacheSyncThreshold = iterationCacheSyncTreshold;
		this.evaluationStatistics = evaluationStatistics == null ? new EvaluationStatistics() : evaluationStatistics;
		this.pipeline = new StandardQueryOptimizerPipeline(this,
				tripleSource, this.evaluationStatistics);
		this.trackResultSize = trackResultSize;
		this.tupleFuncRegistry = tupleFunctionRegistry;
		this.setQueryEvaluationMode(QueryEvaluationMode.STANDARD);
	}

